  6→// ── Slot Colors ────────────────────────────────────────────────────
  7→
  8→export const SLOT_COLORS = {
  9→  clip:         { color: "#FFD500", varName: "--sd-slot-clip" },
 10→  clip_vision:  { color: "#A8DADC", varName: "--sd-slot-clip-vision" },
 11→  conditioning: { color: "#FFA931", varName: "--sd-slot-conditioning" },
 12→  controlnet:   { color: "#6EE7B7", varName: "--sd-slot-controlnet" },
 13→  image:        { color: "#64B5F6", varName: "--sd-slot-image" },
 14→  latent:       { color: "#FF9CF9", varName: "--sd-slot-latent" },
 15→  mask:         { color: "#81C784", varName: "--sd-slot-mask" },
 16→  model:        { color: "#B39DDB", varName: "--sd-slot-model" },
 17→  style_model:  { color: "#C2FFAE", varName: "--sd-slot-style-model" },
 18→  vae:          { color: "#FF6E6E", varName: "--sd-slot-vae" },
 19→  noise:        { color: "#B0B0B0", varName: "--sd-slot-noise" },
 20→  guider:       { color: "#66FFFF", varName: "--sd-slot-guider" },
 21→  sampler:      { color: "#ECB4B4", varName: "--sd-slot-sampler" },
 22→  sigmas:       { color: "#CDFFCD", varName: "--sd-slot-sigmas" },
 23→};
 24→
 25→function _slotColor(slotType) {
 26→  const s = SLOT_COLORS[slotType];
 27→  return s ? s.color : "#9a9caa";
 28→}
 29→
 30→// ── Text Rendering ─────────────────────────────────────────────────
 31→
 32→/**
 33→ * Parse raw text into a DocumentFragment with styled elements.
 34→ * Handles: ```code blocks```, `inline code`, **bold**, paragraph breaks.
 35→ * NO innerHTML — all content via textContent.
 36→ */
 37→export function renderText(rawText) {
 38→  const frag = document.createDocumentFragment();
 39→  if (!rawText) return frag;
 40→
 41→  // Split on triple-backtick code blocks
 42→  const parts = rawText.split(/(```[\s\S]*?```)/);
 43→
 44→  for (const part of parts) {
 45→    if (part.startsWith("```") && part.endsWith("```")) {
 46→      // Code block — strip fences and optional language tag
 47→      let code = part.slice(3, -3);
 48→      // Remove optional language identifier on first line
 49→      const nlIdx = code.indexOf("\n");
 50→      if (nlIdx !== -1 && nlIdx < 20 && /^[a-zA-Z]*$/.test(code.slice(0, nlIdx).trim())) {
 51→        code = code.slice(nlIdx + 1);
 52→      }
 53→      // Trim leading/trailing newline
 54→      if (code.startsWith("\n")) code = code.slice(1);
 55→      if (code.endsWith("\n")) code = code.slice(0, -1);
 56→
 57→      const pre = document.createElement("pre");
 58→      pre.className = "sd-code-block";
 59→      pre.textContent = code;
 60→      frag.appendChild(pre);
 61→    } else {
 62→      // Text content — split into paragraphs on double newlines
 63→      const paragraphs = part.split(/\n{2,}/);
 64→      for (const para of paragraphs) {
 65→        const trimmed = para.trim();
 66→        if (!trimmed) continue;
 67→
 68→        const p = document.createElement("p");
 69→        _appendInlineMarkup(p, trimmed);
 70→        frag.appendChild(p);
 71→      }
 72→    }
 73→  }
 74→
 75→  return frag;
 76→}
 77→
 78→/**
 79→ * Parse inline markup (**bold** and `code`) and append nodes to parent.
 80→ */
 81→function _appendInlineMarkup(parent, text) {
 82→  // Tokenize on **bold** and `code` patterns
 83→  const tokens = text.split(/(\*\*[^*]+\*\*|`[^`]+`)/);
 84→
 85→  for (const token of tokens) {
 86→    if (token.startsWith("**") && token.endsWith("**")) {
 87→      // Bold
 88→      const strong = document.createElement("strong");
 89→      strong.className = "sd-text-bold";
 90→      strong.textContent = token.slice(2, -2);
 91→      parent.appendChild(strong);
 92→    } else if (token.startsWith("`") && token.endsWith("`")) {
 93→      // Inline code
 94→      const code = document.createElement("code");
 95→      code.className = "sd-code-inline";
 96→      code.textContent = token.slice(1, -1);
 97→      parent.appendChild(code);
 98→    } else if (token) {
 99→      _appendInlineText(parent, token);
100→    }
101→  }
102→}
103→
104→/**
105→ * Append plain text, converting single newlines to <br>.
106→ */
107→function _appendInlineText(parent, text) {
108→  const lines = text.split("\n");
109→  for (let i = 0; i < lines.length; i++) {
110→    if (i > 0) parent.appendChild(document.createElement("br"));
111→    if (lines[i]) parent.appendChild(document.createTextNode(lines[i]));
112→  }
113→}
