130→/**
131→ * Create a colored slot tag chip.
132→ * @param {string} label - Node/concept name
133→ * @param {string} slotType - Slot type key (e.g., "model", "vae")
134→ */
135→export function createSlotTag(label, slotType) {
136→  const color = _slotColor(slotType);
137→  const tag = document.createElement("span");
138→  tag.className = "sd-slot-tag";
139→  tag.style.background = color + "1f"; // 12% opacity
140→  tag.style.border = `1px solid ${color}40`; // 25% opacity
141→  tag.style.color = color;
142→
143→  const dot = document.createElement("span");
144→  dot.className = "sd-slot-tag__dot";
145→  dot.style.background = color;
146→  dot.style.boxShadow = `0 0 4px ${color}8c`; // 55% glow
147→  tag.appendChild(dot);
148→
149→  const txt = document.createTextNode(label);
150→  tag.appendChild(txt);
151→
152→  return tag;
153→}
