155→/**
156→ * Create a collapsible section.
157→ * @param {string} title
158→ * @param {string} dotColor - CSS color string
159→ * @param {number|string} count - Badge count
160→ * @param {boolean} defaultOpen
161→ * @param {Function} buildBody - () => HTMLElement (lazy, called on first expand)
162→ */
163→export function createCollapsibleSection(title, dotColor, count, defaultOpen, buildBody) {
164→  const section = document.createElement("div");
165→  section.className = "sd-section" + (defaultOpen ? " sd-section--open" : "");
166→
167→  // Trigger button
168→  const trigger = document.createElement("button");
169→  trigger.className = "sd-section__trigger";
170→
171→  const dot = document.createElement("span");
172→  dot.className = "sd-section__dot";
173→  dot.style.background = dotColor;
174→  dot.style.boxShadow = `0 0 4px ${dotColor}8c`;
175→  trigger.appendChild(dot);
176→
177→  const titleEl = document.createElement("span");
178→  titleEl.className = "sd-section__title";
179→  titleEl.textContent = title;
180→  trigger.appendChild(titleEl);
181→
182→  if (count != null) {
183→    const countEl = document.createElement("span");
184→    countEl.className = "sd-section__count";
185→    countEl.textContent = String(count);
186→    trigger.appendChild(countEl);
187→  }
188→
189→  const chevron = document.createElement("span");
190→  chevron.className = "sd-section__chevron";
191→  chevron.textContent = "\u25b8"; // right-pointing triangle
192→  trigger.appendChild(chevron);
193→
194→  section.appendChild(trigger);
195→
196→  // Body (lazy)
197→  const body = document.createElement("div");
198→  body.className = "sd-section__body";
199→  let built = defaultOpen;
200→  if (defaultOpen && buildBody) {
201→    const content = buildBody();
202→    if (content) body.appendChild(content);
203→  }
204→  section.appendChild(body);
205→
206→  // Toggle
207→  trigger.addEventListener("click", () => {
208→    const isOpen = section.classList.toggle("sd-section--open");
209→    if (isOpen && !built && buildBody) {
210→      built = true;
211→      const content = buildBody();
212→      if (content) body.appendChild(content);
213→    }
214→  });
215→
216→  return section;
217→}
