219→/**
220→ * Create a flow chain showing signal path through nodes.
221→ * @param {Array<{label: string, slotType: string}>} nodes
222→ * @param {string} [pathLabel] - Optional path label prefix
223→ */
224→export function createFlowChain(nodes, pathLabel) {
225→  const chain = document.createElement("div");
226→  chain.className = "sd-flow-chain";
227→
228→  if (pathLabel) {
229→    const lbl = document.createElement("span");
230→    lbl.className = "sd-flow-chain__label";
231→    lbl.textContent = pathLabel;
232→    chain.appendChild(lbl);
233→  }
234→
235→  for (let i = 0; i < nodes.length; i++) {
236→    if (i > 0) {
237→      const arrow = document.createElement("span");
238→      arrow.className = "sd-flow-chain__arrow";
239→      arrow.textContent = "\u2192"; // →
240→      chain.appendChild(arrow);
241→    }
242→
243→    const node = document.createElement("span");
244→    node.className = "sd-flow-chain__node";
245→    const color = _slotColor(nodes[i].slotType);
246→    node.style.color = color;
247→    node.style.background = color + "1a"; // ~10% opacity
248→    node.textContent = nodes[i].label;
249→    chain.appendChild(node);
250→  }
251→
252→  return chain;
253→}
