342→/**
343→ * Create a full panel from panelData.
344→ * @param {Object} panelData - Panel schema from backend
345→ * @returns {HTMLElement|null}
346→ *
347→ * panelData schema:
348→ * {
349→ *   type: "workflow_analysis"|"discovery"|"execution"|"error",
350→ *   header: { label, badge, title, summary, stats: [{value,label}] },
351→ *   sections: [{
352→ *     title, dotColor, count, defaultOpen,
353→ *     type: "flow_chain"|"slot_tags"|"capability_rows"|"detail_rows",
354→ *     data: { ... type-specific ... }
355→ *   }],
356→ *   footer: { status, actions: [{label,variant}] }
357→ * }
358→ */
359→export function createPanel(panelData) {
360→  if (!panelData) return null;
361→
362→  const panel = document.createElement("div");
363→  panel.className = "sd-panel";
364→
365→  // Header
366→  if (panelData.header) {
367→    const header = document.createElement("div");
368→    header.className = "sd-panel__header";
369→
370→    // Label row
371→    const labelRow = document.createElement("div");
372→    labelRow.className = "sd-panel__label-row";
373→
374→    const label = document.createElement("span");
375→    label.className = "sd-panel__label";
376→    label.textContent = panelData.header.label || "";
377→    labelRow.appendChild(label);
378→
379→    if (panelData.header.badge) {
380→      const badge = document.createElement("span");
381→      badge.className = "sd-panel__badge";
382→      badge.textContent = panelData.header.badge;
383→      labelRow.appendChild(badge);
384→    }
385→    header.appendChild(labelRow);
386→
387→    // Title
388→    if (panelData.header.title) {
389→      const title = document.createElement("div");
390→      title.className = "sd-panel__title";
391→      title.textContent = panelData.header.title;
392→      header.appendChild(title);
393→    }
394→
395→    // Summary
396→    if (panelData.header.summary) {
397→      const summary = document.createElement("div");
398→      summary.className = "sd-panel__summary";
399→      summary.textContent = panelData.header.summary;
400→      header.appendChild(summary);
401→    }
402→
403→    // Stats
404→    if (panelData.header.stats && panelData.header.stats.length) {
405→      const stats = document.createElement("div");
406→      stats.className = "sd-panel__stats";
407→      for (const s of panelData.header.stats) {
408→        const stat = document.createElement("div");
409→        stat.className = "sd-panel__stat";
410→
411→        const val = document.createElement("span");
412→        val.className = "sd-panel__stat-value";
413→        val.textContent = String(s.value);
414→        stat.appendChild(val);
415→
416→        const lbl = document.createElement("span");
417→        lbl.className = "sd-panel__stat-label";
418→        lbl.textContent = s.label;
419→        stat.appendChild(lbl);
420→
421→        stats.appendChild(stat);
422→      }
423→      header.appendChild(stats);
424→    }
425→
426→    panel.appendChild(header);
427→  }
428→
429→  // Sections
430→  if (panelData.sections) {
431→    for (const sec of panelData.sections) {
432→      const dotColor = sec.dotColor || "var(--sd-brand)";
433→      const section = createCollapsibleSection(
434→        sec.title,
435→        dotColor,
436→        sec.count,
437→        sec.defaultOpen || false,
438→        () => _buildSectionBody(sec)
439→      );
440→      panel.appendChild(section);
441→    }
442→  }
443→
444→  // Footer
445→  if (panelData.footer) {
446→    const footer = createActionFooter(
447→      panelData.footer.status,
448→      panelData.footer.actions
449→    );
450→    panel.appendChild(footer);
451→  }
452→
453→  return panel;
454→}
