145→  const statusEl = el.querySelector("#sd-status");
146→  const stageBar = el.querySelector("#sd-stage");
147→  const stageLabel = el.querySelector("#sd-stage-label");
148→  const stageDetail = el.querySelector("#sd-stage-detail");
149→
150→  let busy = false;
151→  let streamingEl = null;     // element receiving streamed text deltas
152→  let streamAccum = "";       // accumulated text during streaming
153→  let typingIndicator = null; // typing dots shown during stream
154→
155→  function scrollToBottom() {
156→    messagesEl.scrollTop = messagesEl.scrollHeight;
157→  }
158→
159→  function setStage(stage, detail) {
160→    if (stage === "DONE" || !stage) {
161→      stageBar.style.display = "none";
162→      return;
163→    }
164→    stageBar.style.display = "flex";
165→    stageLabel.textContent = stage;
166→    stageDetail.textContent = detail || "";
167→  }
168→
169→  function setBusy(state) {
170→    busy = state;
171→    sendBtn.disabled = state;
172→    inputEl.disabled = state;
173→    sendBtn.textContent = state ? "..." : "Send";
174→  }
175→
176→  /* ── WebSocket message handler ────────────────────────────────── */
177→
178→  function handleAgentMessage(data) {
179→    switch (data.type) {
180→      case "connected":
181→        break;
182→
183→      case "text_delta":
184→        // Streaming: show typing indicator, accumulate text
185→        if (!streamingEl) {
186→          streamingEl = document.createElement("div");
187→          streamingEl.className = "sd-message sd-message--agent";
188→
189→          const label = document.createElement("span");
190→          label.className = "sd-message__label";
191→          label.textContent = "Agent";
192→          streamingEl.appendChild(label);
193→
194→          const body = document.createElement("div");
195→          body.className = "sd-message__body sd-text-body";
196→          streamingEl.appendChild(body);
197→
198→          messagesEl.appendChild(streamingEl);
199→          streamAccum = "";
200→        }
201→
202→        streamAccum += data.text;
203→
204→        // Show typing indicator during streaming
205→        const streamBody = streamingEl.querySelector(".sd-message__body");
206→        if (!typingIndicator) {
207→          typingIndicator = createTypingIndicator();
208→          streamBody.appendChild(typingIndicator);
209→        }
210→
211→        scrollToBottom();
212→        break;
213→
214→      case "message": {
215→        // Full message — render with rich text, replacing streaming element
216→        const finalText = data.content || streamAccum;
217→
218→        if (streamingEl) {
219→          // Replace streaming content with final rendered text
220→          const body = streamingEl.querySelector(".sd-message__body");
221→          body.textContent = ""; // clear typing indicator
222→          body.classList.add("sd-text-body");
223→          body.appendChild(renderText(finalText));
224→          streamingEl = null;
225→          streamAccum = "";
226→          typingIndicator = null;
227→        } else {
228→          messagesEl.appendChild(createMessageEl("agent", finalText));
229→        }
230→        scrollToBottom();
231→        break;
232→      }
233→
234→      case "panel": {
235→        // Structured panel from tool result
236→        const panelEl = createPanel(data.panel);
237→        if (panelEl) {
238→          // Wrap in a message container for consistent spacing
239→          const wrapper = document.createElement("div");
240→          wrapper.className = "sd-message sd-message--agent";
241→          wrapper.style.padding = "0";
242→          wrapper.style.background = "none";
243→          wrapper.appendChild(panelEl);
244→          messagesEl.appendChild(wrapper);
245→          scrollToBottom();
246→        }
247→        break;
248→      }
249→
250→      case "stage":
251→        setStage(data.stage, data.detail);
252→        if (data.stage === "DONE") {
253→          // Clean up streaming state
254→          if (streamingEl && streamAccum) {
255→            const body = streamingEl.querySelector(".sd-message__body");
256→            body.textContent = "";
257→            body.classList.add("sd-text-body");
258→            body.appendChild(renderText(streamAccum));
259→          }
260→          streamingEl = null;
261→          streamAccum = "";
262→          typingIndicator = null;
263→          setBusy(false);
264→        }
265→        break;
266→
267→      case "error":
268→        setStage(null);
269→        messagesEl.appendChild(createMessageEl("system", data.message));
270→        streamingEl = null;
271→        streamAccum = "";
272→        typingIndicator = null;
273→        setBusy(false);
274→        scrollToBottom();
275→        break;
276→
277→      default:
278→        console.log("[SUPER DUPER] Unknown event:", data);
279→    }
280→  }
281→
282→  function handleStatus(status) {
283→    statusEl.textContent = status === "connected" ? "" : status;
284→    statusEl.className = `sd-header__status sd-header__status--${status}`;
285→  }
286→
287→  /* ── Connect ──────────────────────────────────────────────────── */
288→
289→  const conn = new AgentConnection(handleAgentMessage, handleStatus);
290→  conn.connect();
291→
292→  /* ── Send message ─────────────────────────────────────────────── */
293→
294→  async function sendMessage() {
295→    const text = inputEl.value.trim();
296→    if (!text || busy) return;
297→
298→    // Show user message
299→    messagesEl.appendChild(createMessageEl("user", text));
300→    inputEl.value = "";
301→    scrollToBottom();
302→
303→    // Capture current workflow from ComfyUI canvas
304→    let workflow = null;
305→    try {
306→      const result = await app.graphToPrompt();
307→      if (result && result.output) {
308→        workflow = result.output;
309→      }
310→    } catch (e) {
311→      console.warn("[SUPER DUPER] Could not capture workflow:", e);
312→    }
313→
314→    // Send to agent via WebSocket (include workflow if captured)
315→    const payload = { content: text };
316→    if (workflow) {
317→      payload.workflow = workflow;
318→    }
319→    const sent = conn.send("chat", payload);
320→    if (!sent) {
321→      messagesEl.appendChild(
322→        createMessageEl("system", "Not connected. Reconnecting...")
323→      );
324→      scrollToBottom();
325→      return;
326→    }
327→
328→    setBusy(true);
329→  }
330→
331→  sendBtn.addEventListener("click", sendMessage);
332→  inputEl.addEventListener("keydown", (e) => {
333→    if (e.key === "Enter" && !e.shiftKey) {
334→      e.preventDefault();
335→      sendMessage();
336→    }
337→  });
338→
339→  setTimeout(() => inputEl.focus(), 100);
340→}
341→
